]// Round 21 lead audit (read-only): one playable screen of the REAL game at start / early / middle / late / end and hard
// left / right, deterministic (fixed sim steps, frozen shader clock, one frame rendered per shot, no real-time steps).
// Run from the worktree whose build you want to see (vite serves the current directory):
//   cd <worktree> && node /home/user/rainbow-/tools/lead21/audit_screen.mjs <outDir> <stage 04..08> "<query>"
// Shots are fractions of the stage from its checkpoint to its end; env AUDIT_SHOTS='[["name",frac,steer],...]' overrides.
import { mkdirSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [OUT, STAGE, Q] = process.argv.slice(2);
const SHOTS = process.env.AUDIT_SHOTS ? JSON.parse(process.env.AUDIT_SHOTS)
  : [['a_start', 0, null], ['b_early', 0.12, null], ['c_middle', 0.35, null], ['d_late', 0.6, null], ['e_end', 0.85, null],
     ['f_hard_left', 0.35, -1], ['g_hard_right', 0.35, 1]];
mkdirSync(OUT, { recursive: true });
const { chromium } = loadPlaywright();
const vite = await startVite(Number(process.env.AUDIT_PORT ?? 5290));
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
const log = [];
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  page.on('pageerror', (e) => console.error('pageerror', e.message));
  page.on('console', (m) => { if (m.type() === 'error' && /Shader|WebGL|rror/.test(m.text())) console.error('console', m.text().slice(0, 160)); });
  await page.goto(`${vite.url}/?qa=1&dpr=1&${Q}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
  for (const [name, frac, steer] of SHOTS) {
    const st = await page.evaluate(async ([stage, frac, steer]) => {
      const r = window.__rainbow;
      r.goto(stage);
      const s0 = r.state().s, s1 = r.course.stage(stage).s1;
      const tS = s0 + frac * (s1 - s0);
      r.setSteer(steer);
      let k = 0; while (r.state().s < tS && k < 6000) { r.step(1); k++; }
      r.setSteer(null);
      r.freezeAt(10);
      r.drawList();
      await new Promise((res) => requestAnimationFrame(() => res()));
      return { ...r.state(), s0, s1 };
    }, [STAGE, frac, steer]);
    await page.screenshot({ path: `${OUT}/${name}.png` });
    log.push({ name, frac, steer, s: st.s, lat: st.lat, stage: st.stage, coins: st.coins, s0: st.s0, s1: st.s1 });
    console.log(STAGE, name, 's', st.s, 'lat', st.lat, 'stage', st.stage, 'coins', st.coins);
  }
} finally { writeFileSync(`${OUT}/shots.json`, JSON.stringify(log, null, 1)); await browser.close(); await vite.close?.(); }

1	/**
2	 * `?match07=1` — Screen 07 approved-picture test (2026-11-17, qa/match/07/NOTES.md), the Screen 08 method.
3	 * REAL 3D proxy geometry of "Dive the Washer Tube", solved from the user's approved Screen 07 and the locked game camera
4	 * (tools/match07/solve_cam07.py → cam07_locked.json, tools/match07/fit_proxies07.py → proj07.json): the purple tube (a
5	 * cylinder along the game's 07 tube axis, radius and ring depths fitted to the painted gold rings), the water plane at
6	 * Benny's water level (the painted S-river, foam banks, bubbles) and the five paddles upper-left (blocks standing out of
7	 * the wall at the painted spots).
8	 * Every surface is textured by camera projection of the user's ORIGINAL approved pixels (HUD, title, Benny and coins
9	 * provisionally filled locally: assets/textures/match07/plate07_hybrid.png) from that locked camera, so the locked view
10	 * shows the approved scenery and a moving camera sees it on geometry (parallax). Surfaces the picture never showed, or
11	 * showed much farther / more edge-on than the moving camera sees them (stretch guard + projector depth test), get
12	 * RING-STRUCTURED tiles unwrapped from the artwork: the painted wall bay repeats every ring spacing along the tube (rings
13	 * stay rings deep inside the tube, no smears), the painted river repeats along the water. The shader undoes the game's
14	 * post chain (PROJ05_INVERSE) and takes no fog. Without the switch nothing in this file runs and the game is unchanged.
15	 */
16	import * as THREE from 'three';
17	import { RoundedBoxGeometry } from 'three/examples/jsm/geometries/RoundedBoxGeometry.js';
18	import { PROJ05_INVERSE, flag05 } from '../vfx/waterRibbon';
19	import type { Course } from './course';
20	
21	interface Layout07 {
22	  camera: { matrixWorld: number[]; fov: number; size: [number, number] };
23	  D: [number, number, number];
24	  U: [number, number, number];
25	  X: [number, number, number];
26	  water: [number, number, number];
27	  tube: { r: number; ax: number; h: number };
28	  rings: Record<string, number>;
29	  paddles: { pos: [number, number, number]; along: number; angleDeg: number; w: number }[];
30	}
31	interface Tiles07 { wall: { theta: [number, number]; along: [number, number]; bay: number }; river: { lateral: [number, number]; along: [number, number] } }
32	
33	export interface Match07 {
34	  group: THREE.Group;
35	  bakeDepth(renderer: THREE.WebGLRenderer): void;
36	  sync(renderer: THREE.WebGLRenderer, w: number, h: number): void;
37	  /** M3 '?m07tube=1': true from the hand-over point on — the plunge tube shows and the fitted proxy ends at its depth */
38	  setPlunge(on: boolean): void;
39	}
40	
41	const VERT = /* glsl */ `
42	uniform mat4 uProjVP;
43	uniform float uCtr[64];   // r16 '?m07nearw=1': river centre line (tube-local x) every uCtrA.y units of depth from uCtrA.x
44	uniform vec3 uCtrA;       // first depth, step, on (z)
45	varying vec4 vProj;
46	varying vec3 vW;
47	varying vec3 vN;
48	varying vec3 vL;
49	varying vec2 vUv;
50	varying float vCtr;
51	void main() {
52	  vUv = uv;
53	  vec4 wp = modelMatrix * vec4(position, 1.0);
54	  vProj = uProjVP * wp;
55	  vW = wp.xyz;
56	  vL = (uGroupInv * wp).xyz;
57	  vCtr = 0.0;
58	  if (uCtrA.z > 0.5) {
59	    float ia = clamp((-vL.z - uCtrA.x) / uCtrA.y, 0.0, 62.999);
60	    int i0 = int(floor(ia));
61	    vCtr = mix(uCtr[i0], uCtr[i0 + 1], ia - float(i0));
62	  }
63	  vN = normalize(mat3(modelMatrix) * normal);
64	  gl_Position = projectionMatrix * viewMatrix * wp;
65	}`;
66	
67	const FRAG = /* glsl */ `
68	uniform sampler2D uPlate;
69	uniform sampler2D uDepth;
70	uniform float uUseDepth;
71	uniform vec2 uNearFar;
72	uniform sampler2D uTile;
73	uniform float uMode;      // 0 = triplanar patch, 1 = tube wall unwrap, 2 = river unwrap
74	uniform float uPatchK;
75	uniform vec4 uTube;       // ax, h, ring R2 depth, bay length
76	uniform vec2 uTheta;      // unwrap angle range (rad): right water line .. left water line over the top
77	uniform vec4 uRiver;      // lateral min, lateral max, along min, along max
78	uniform vec3 uProjPos;
79	uniform vec4 uPjPost;
80	uniform vec2 uPjRes;
81	uniform sampler2D uFill;   // M2 '?m07fill=1': provisional-fill mask of the plate (1 = filled, not original pixels)
82	uniform float uFillTile;  // 1 = on the water, filled plate pixels give way to the river tile
83	uniform vec2 uAng;        // M2 '?m07ang=1': view-vs-projector angle cosines (full plate above x, tile below y); x < 0 = off
84	uniform float uGoldLit;   // M2 '?m07gold=1': paddle blocks shaded as solid polished gold where the picture does not cover them
85	uniform vec3 uKey;        // world direction toward the key light (from the viewer's side and above, so the faces the camera sees are lit)
86	uniform float uClip;      // M3 '?m07tube=1': proxy surfaces end at this depth along the tube axis (the plunge tube continues); 0 = off
87	uniform vec2 uGuard;      // stretch guard thresholds (M1/M2 2.2..4.5; M3 '?m07near=1' tighter)
88	uniform vec2 uFade;       // M3 plunge river: fades out between these arc depths (the game's own water continues into 08)
89	uniform float uNearOn;    // r16 '?m07nearw=1': the level-stretch water tile = the painted NEAR river (near_bank / near_foam)
90	uniform vec4 uNearW;      // river half-width incl. the magenta band, magenta band width, bank-tile period along, foam-tile size
91	uniform float uNearM;     // share of the bank tile's columns that is the magenta band (column 0 = its outer edge)
92	uniform sampler2D uNearTile;
93	uniform sampler2D uFoamTile;
94	uniform vec3 uWF;         // r16 '?m07wfoam=1': foam clouds piled on the lowest wall band — base height, cloud-top height, on (z)
95	uniform vec4 uBand;       // r18 '?m07band=1': S-sweep of the river centre off Benny's lane: amplitude, wavelength, phase (along), on (w)
96	uniform vec4 uBand2;      // r18 m07band: reach of Benny's lane (lane ± steer + body), cyan core half-width, min band width, foam-edge wobble
97	varying vec2 vUv;
98	varying vec4 vProj;
99	varying vec3 vW;
100	varying vec3 vN;
101	varying vec3 vL;
102	varying float vCtr;
103	${PROJ05_INVERSE}
104	// r16 m07nearw: [foam | magenta | trim | cyan | cyan | trim | magenta | foam] across a winding centre line, world-anchored.
105	// Both banks are the painted lower-left band straightened (tools/match07/near_tiles_r16.py) at about the painted near
106	// scale; the right bank reads another stretch of the strip (no mirror image across the centre).
107	vec3 nearWater() {
108	  float along = -vL.z;
109	  float d = vL.x - vCtr;
110	  float R = uNearW.x, mw = uNearW.y;
111	  float Rc = R - mw;                       // cyan core half-width
112	  float Ro = R;                            // outer edge of the magenta band (foam beyond)
113	  if (uBand.w > 0.5) {
114	    // r18 m07band: the painted near river — a narrow glossy cyan core with THICK magenta satin bands close beside Benny, the
115	    // core sweeping in a world-anchored S off his lane (so the bands curve across the view as he swims, like the painted
116	    // S-sweeps); on the outside of each bend the band widens to cover everywhere Benny can steer (never foam under him)
117	    float S = uBand.x * sin(6.2831853 * (along - uBand.z) / uBand.y);
118	    d -= S;
119	    float reach = (d > 0.0 ? -S : S) + uBand2.x;
120	    Rc = uBand2.y;
121	    Ro = max(Rc + uBand2.z, reach);
122	  }
123	  float a = abs(d);
124	  float u;
125	  if (a < Rc) u = uNearM + (1.0 - uNearM) * (1.0 - a / Rc);
126	  else if (uBand.w > 0.5) {
127	    // the band tile's magenta columns spread across the whole (varying) band width (wide soft satin highlights where the band
128	    // is thick; no mirrored repeats, which read as a diamond lattice)
129	    u = uNearM * (1.0 - clamp((a - Rc) / max(Ro - Rc, 1e-3), 0.0, 1.0));
130	  } else u = uNearM * clamp((R - a) / mw, 0.0, 1.0);
131	  float v = along / uNearW.z;
132	  vec3 cL = texture2D(uNearTile, vec2(u, v)).rgb;
133	  vec3 cR = texture2D(uNearTile, vec2(u, v + 0.5)).rgb;
134	  vec3 river = mix(cL, cR, smoothstep(-0.32, 0.32, d));
135	  R = Ro;
136	  // r18 m07band: a scalloped (puffy) foam line along the band's outer edge instead of a straight cut
137	  if (uBand.w > 0.5) R += uBand2.w * (0.6 * sin(along * 2.3 + sign(d) * 1.7) + 0.4 * sin(along * 5.1 + 0.4 + sign(d)));
138	  // painted foam clouds on the banks: two offset readings of the foam tile blended by a slow world mask (no wallpaper grid)
139	  vec2 fp = vec2(vL.x, along) / uNearW.w;
140	  vec3 f1 = texture2D(uFoamTile, fp).rgb;
141	  vec3 f2 = texture2D(uFoamTile, vec2(fp.y, -fp.x) * 0.77 + vec2(0.31, 0.57)).rgb;
142	  float fm = smoothstep(0.25, 0.75, 0.5 + 0.35 * sin(fp.x * 1.9 + 1.4 * sin(fp.y * 1.1)) + 0.25 * sin(fp.y * 1.6 + 0.8));
143	  vec3 foam = mix(f1, f2, fm);
144	  return mix(river, foam, smoothstep(R - 0.04, R + 0.10, a));
145	}
146	// r16 m07wfoam: the painted foam clouds piled where the tube wall meets the water (no hard wall / floor edge when steering hard);
147	// a scalloped cloud-top line along the wall, world-anchored, the foam tile from the lower-right painted bank
148	vec3 wallFoam(vec3 c, float hy, float along, float side) {
149	  float k = along * 1.35 + side * 3.1;
150	  float b1 = pow(abs(sin(k + 0.8 * sin(along * 0.43 + side))), 0.55);
151	  float b2 = pow(abs(sin(k * 2.3 + 1.7)), 0.6);
152	  float hE = uWF.x + uWF.y * (0.65 * b1 + 0.35 * b2);
153	  float f = 1.0 - smoothstep(hE - 0.05, hE + 0.03, hy);
154	  vec3 foam = texture2D(uFoamTile, vec2(along, hy + side * 0.37) / 1.1).rgb;
155	  foam *= 0.9 + 0.14 * smoothstep(hE - 0.3, hE, hy);   // brighter cloud tops, softer shade toward the water
156	  return mix(c, foam, f);
157	}
158	vec3 riverTile() {
159	  float u = (vL.x - uRiver.x) / (uRiver.y - uRiver.x);
160	  u = 1.0 - abs(mod(u, 2.0) - 1.0);                       // mirrored across the banks
161	  float v = fract((-vL.z - uRiver.z) / (uRiver.w - uRiver.z));
162	  return texture2D(uTile, vec2(u, v)).rgb;
163	}
164	vec3 tileColor() {
165	  // M3 '?m07tube=1' plunge surfaces (real geometry along the course): uv = (arc depth along the tube, angle / lateral)
166	  if (uMode > 3.5) {
167	    float u = (vUv.x - uRiver.x) / (uRiver.y - uRiver.x);
168	    u = 1.0 - abs(mod(u, 2.0) - 1.0);
169	    float v = fract((vUv.y - uRiver.z) / (uRiver.w - uRiver.z));
170	    return texture2D(uTile, vec2(u, v)).rgb;
171	  }
172	  if (uMode > 2.5) {
173	    float u = fract((vUv.x - uTube.z) / uTube.w);
174	    float v = clamp((vUv.y - uTheta.x) / (uTheta.y - uTheta.x), 0.0, 1.0);
175	    return texture2D(uTile, vec2(u, v)).rgb;
176	  }
177	  if (uMode > 1.5) {
178	    if (uNearOn > 0.5) return nearWater();
179	    return riverTile();
180	  }
181	  if (uMode > 0.5) {
182	    float a = atan(vL.y - uTube.y, vL.x - uTube.x);
183	    if (a < -1.5707963) a += 6.2831853;
184	    float v = clamp((a - uTheta.x) / (uTheta.y - uTheta.x), 0.0, 1.0);
185	    float u = fract((-vL.z - uTube.z) / uTube.w);
186	    vec3 wc = texture2D(uTile, vec2(u, v)).rgb;
187	    if (uWF.z > 0.5) wc = wallFoam(wc, vL.y, -vL.z, sign(vL.x - uTube.x));
188	    return wc;
189	  }
190	  vec3 n = abs(normalize(vN)); n /= max(n.x + n.y + n.z, 1e-4);
191	  vec3 p = vL * uPatchK;
192	  vec3 g = texture2D(uTile, p.zy).rgb * n.x + texture2D(uTile, p.xz).rgb * n.y + texture2D(uTile, p.xy).rgb * n.z;
193	  if (uGoldLit > 0.5) {
194	    vec3 nw = normalize(vN); vec3 vv = normalize(cameraPosition - vW);
195	    if (dot(nw, vv) < 0.0) nw = -nw;
196	    // saturated polished gold (the painted paddles' orange-gold), the patch only adds texture variation
197	    float lum = dot(g, vec3(0.299, 0.587, 0.114));
198	    float dif = 0.25 + 0.85 * max(dot(nw, uKey), 0.0);
199	    float spec = pow(max(dot(reflect(-uKey, nw), vv), 0.0), 24.0);
200	    float rim = pow(1.0 - max(dot(nw, vv), 0.0), 2.0);
201	    g = vec3(1.0, 0.58, 0.18) * (0.55 + 0.6 * lum) * dif + vec3(1.0, 0.9, 0.62) * (0.8 * spec + 0.45 * rim);
202	  }
203	  return g;
204	}
205	float linZ(float d) { float n = uNearFar.x, f = uNearFar.y; float z = d * 2.0 - 1.0; return 2.0 * n * f / (f + n - z * (f - n)); }
206	void main() {
207	  if (uClip > 0.0 && uMode < 2.5 && -vL.z > uClip) discard;
208	  vec3 pc = tileColor();
209	  if (uMode > 2.5) {
210	    // plunge surfaces: never in the approved picture → the ring-bay / river tiles only, world-anchored
211	    float a = uMode > 3.5 ? 1.0 - smoothstep(uFade.x, uFade.y, vUv.y) : 1.0;
212	    if (a < 0.003) discard;
213	    gl_FragColor = vec4(pjInverse(pc), a);
214	    return;
215	  }
216	  vec3 t = pc;
217	  vec3 nn = normalize(vN);
218	  float cp = abs(dot(nn, normalize(uProjPos - vW))), cc = abs(dot(nn, normalize(cameraPosition - vW)));
219	  // stretch + magnification guard: the projection is used where the current view sees the surface no more face-on and
220	  // no more magnified than the approved view did (incidence-cosine ratio x distance ratio = 1 in the approved view)
221	  float mag = (cc / max(cp, 1e-3)) * (distance(uProjPos, vW) / max(distance(cameraPosition, vW), 1e-3));
222	  float keep = 1.0 - smoothstep(uGuard.x, uGuard.y, mag);
223	  if (vProj.w > 0.0) {
224	    vec3 ndc = vProj.xyz / vProj.w;
225	    vec2 uv = ndc.xy * 0.5 + 0.5;
226	    if (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
227	      float vis = 1.0;
228	      if (uUseDepth > 0.5) {
229	        float zs = linZ(texture2D(uDepth, uv).r), zf = linZ(ndc.z * 0.5 + 0.5);
230	        vis = 1.0 - smoothstep(0.015 * zs, 0.04 * zs + 0.05, zf - zs);
231	      }
232	      float w = vis * keep;
233	      // M2 '?m07fill=1': on the water, the provisional fill (Benny / coins in the picture) gives way to the river tile
234	      if (uFillTile > 0.5 && uMode > 1.5) w *= 1.0 - texture2D(uFill, uv).r;
235	      // M2 '?m07ang=1': painted relief (ring flanges, paddles) flattened on the proxy doubles when seen from another
236	      // direction: use the picture only where the view direction is close to the approved view's (identical there)
237	      if (uAng.x > 0.0) w *= smoothstep(uAng.y, uAng.x, dot(normalize(cameraPosition - vW), normalize(uProjPos - vW)));
238	      // m07gold (round 4): the paddle blocks show the picture only near the approved view direction; seen from beside or
239	      // below while passing they are solid polished gold (no picture of the wall smeared over their faces)
240	      if (uGoldLit > 0.5 && uMode < 0.5) w *= smoothstep(0.970, 0.995, dot(normalize(cameraPosition - vW), normalize(uProjPos - vW)));
241	      // r16 m07nearw: where the approved view itself looks (no magnification) the provisional fill keeps the old river tile, so
242	      // the approved start view stays exactly as it was; the painted near river takes over as the view magnifies the water
243	      vec3 pcf = pc;
244	      if (uNearOn > 0.5 && uMode > 1.5) pcf = mix(pc, riverTile(), keep * vis);
245	      t = mix(pcf, texture2D(uPlate, uv).rgb, w);
246	    }
247	  }
248	  gl_FragColor = vec4(pjInverse(t), 1.0);
249	}`;
250	
251	const tex = (f: string) => new URL(`../../assets/textures/match07/${f}`, import.meta.url).href;
252	/** r18: numeric URL tunable (QA only), default when absent or not a number */
253	const num07 = (k: string, def: number) => {
254	  const v = typeof location !== 'undefined' ? parseFloat(new URLSearchParams(location.search).get(k) ?? '') : NaN;
255	  return Number.isFinite(v) ? v : def;
256	};
257	
258	/** M3 '?m07tube=1': the plunge continuation needs the course (arc samples) and where it starts / ends */
259	export interface Plunge07 { course: Course; sA: number; sB: number; fade: [number, number] }
260	
261	export async function buildMatch07(plunge?: Plunge07): Promise<Match07> {
262	  const [L, TL]: [Layout07, Tiles07] = await Promise.all([fetch(tex('proj07.json')).then((r) => r.json()), fetch(tex('tiles07.json')).then((r) => r.json())]);
263	  const load = async (f: string, wrap: THREE.Wrapping) => {
264	    const t = await new THREE.TextureLoader().loadAsync(tex(f));
265	    t.colorSpace = THREE.NoColorSpace; // raw display values: the shader inverts the post chain itself
266	    t.wrapS = t.wrapT = wrap; t.minFilter = THREE.LinearMipmapLinearFilter; t.anisotropy = 8;
267	    return t;
268	  };
269	  // MILESTONE 2 test switches (one factor each, qa/match/07/m2/NOTES.md); off = the MILESTONE 1 result unchanged
270	  const fixFill = flag05('m07fill');
